// ==== anim.c
/* 17C1:0000: tile and attribute pointers of any room (room 0 = the dummy room) */
void room_pointers(uint8_t room) { get_room_address(room); }
/* 1375:2620: is the tile on screen (drawn room, or the edge column/row shared with the left, lower and lower-left rooms)? */
int tile_visible(int8_t tilepos, uint8_t room)
{
	if (room == drawn_room) return 1;
	if (room == room_L && tilepos % 10 == 9) return 1;
	if (room == room_B && tilepos < 10) return 1;
	if (room == room_BL && tilepos == 9) return 1;
	return 0;
}
/* kind 5 (level 1) handlers, OVL 33FD; their redraw requests go to the renderer (weak hooks, shell.c) */

void anim_torch_25(void)   /* 33FD:0652: cycles 0..7 while visible */
{
	if (!tile_visible(cur_trob.tilepos, cur_trob.room)) { cur_trob.state = 0xFF; return; }
	uint16_t v = (uint16_t)anim_mod & 0xF; v = v == 7 ? 0 : v + 1;
	anim_mod = (anim_mod & ~0xFu) | v;
	hook_roof_tick(0x25, (int8_t)cur_trob.tilepos, v);   /* 33FD:0680 */
}
void anim_26(void)         /* 33FD:08A2 */
{
	uint16_t v = (uint16_t)anim_mod + 1; anim_mod = (anim_mod & 0xFFFF0000u) | v;
	if (v > 0xB0) { cur_trob.state = 0xFF; return; }
	hook_roof_tick(0x26, (int8_t)cur_trob.tilepos, v);   /* 33FD:08C0 */
}
void anim_27(void)         /* 33FD:058A */
{
	if ((uint16_t)anim_mod >= 0xB) { cur_trob.state = 0xFF; return; }
	anim_mod = (anim_mod & 0xFFFF0000u) | (uint16_t)((uint16_t)anim_mod + 1);
	if ((uint16_t)anim_mod == 1) play_sound(0x31);
	hook_roof_tick(0x27, (int8_t)cur_trob.tilepos, (uint16_t)anim_mod);   /* 33FD:05AC */
}
/* 1375:04CE: animations off screen stop */
int anim_visible(void) { int v = tile_visible(cur_trob.tilepos, cur_trob.room); if (!v) cur_trob.state = 0xFF; return v; }
   /* the entry animate_tiles is at (1375:0006 passes it on: 1375:08D0's argument) */
void anim_torch(void)
{
	if (!anim_visible()) return;
	int cur = (uint8_t)anim_mod, v;
	if (level_kind == 3) { v = random_2751(8); if (v == cur) { v++; if (v >= 9) v = 0; } }
	else v = ovl_torch_347c(cur);
	anim_mod = (anim_mod & 0xFFFF0000u) | (uint16_t)(((uint16_t)anim_mod & 0xFF00) + v);
	if (word_2ba4 == 0 || ((uint8_t)(tick + anim_index) & 1)) hook_trob_request(0x1F4, 0);   /* (late: every other tick, torch by torch) */
}
/* 1375:088C: tile 0x0A cycles 0..0x1B while visible */
void anim_0a(void)
{
	if (anim_tile != 0xA) { cur_trob.state = 0xFF; return; }
	if ((int8_t)cur_trob.state < 0 || !anim_visible()) return;
	int v = (uint8_t)anim_mod & 0x1F; v = v >= 0x1B ? 0 : v + 1;
	anim_mod = (anim_mod & 0xFFFF0000u) | (uint16_t)(((uint16_t)anim_mod & 0xFFE0) | v);
	hook_trob_request(0x2D0, 0);
}
/* 1375:0C66: the level door opens (states 0..3, +1 up to 0x2A) or closes (4.., DS:0764 speeds) */
void anim_exit_door(void)
{
	int si = (uint8_t)anim_mod;
	if ((int8_t)cur_trob.state >= 0) {
		if (cur_trob.state >= 4) {
			cur_trob.state++;
			si -= exit_door_speed(cur_trob.state);
			if (si < 0) { si = 0; cur_trob.state = 0xFF; play_sound(9); }
		} else if (++si >= 0x2A) { cur_trob.state = 0xFF; if (!(drawn_room == 4 && level_number == 13)) play_sound(8); }
		else if (!(drawn_room == 4 && level_number == 13)) play_sound(7);
	}
	anim_mod = (anim_mod & 0xFFFF0000u) | (uint16_t)(((uint16_t)anim_mod & 0xFF00) + si);
	hook_trob_request(0x274, 0);
}
/* 1375:13C0: a torch starts at a random frame */
void start_torch(int8_t tp, uint8_t room)
{
	int r = random_2751(level_kind == 3 ? 8 : 3);
	uint16_t *a = (uint16_t *)&anim_attrs[tp]; *a = (*a & 0xFF00) + r;
	add_trob(0x13, 1, tp, room);
}
/* 1375:1160 */
void start_0a(int8_t tp, uint8_t room)
{
	int r = random_2751(0x1A) + 1;
	uint16_t *a = (uint16_t *)&anim_attrs[tp]; *a = (*a & 0xFFE0) | r;
	add_trob(0xA, 1, tp, room);
}
/* 1375:0096 */
void animate_tile(void)
{
	room_pointers(cur_trob.room);
	anim_mod = anim_attrs[(int8_t)cur_trob.tilepos]; anim_tile = anim_tiles[(int8_t)cur_trob.tilepos];   /* 1375:1A20 */
	uint8_t t = cur_trob.tile;
	if (level_kind == 5 && t == 0x25) anim_torch_25();
	else if (level_kind == 5 && t == 0x26) anim_26();
	else if (level_kind == 5 && t == 0x27) anim_27();
	else if (t == 4 && level_kind == 1) anim_gate_kind1();   /* 33FD:0538 */
	else if (t == 4) anim_gate();
	else if ((t == 0x1C || t == 0x1D) && level_kind == 1) anim_wave_kind1();   /* 33FD:06E4 / 0658 (kind1.c) */
	else if (t == 0x1E && level_kind == 1) anim_tile1e();   /* 33FD:07CE */
	else if (t == 5 || t == 6 || t == 0x22) anim_button();
	else if (t == 0xA) anim_0a();
	else if (t == 0xB) anim_loose();
	else if (t == 0x11) anim_exit_door();
	else if (t == 0x13 || t == 0x20) anim_torch();
	else if (t == 0x24 && level_kind == 3) anim_rock();   /* 33FD:017C */
	else if (t == 0x17 && level_kind == 3) anim_floor();   /* 33FD:05AE */
	else if (t == 0xD && (level_kind == 2 || level_kind == 4)) anim_blade();   /* 33FD:0000 (OVL05) */
	else if (t == 0x2C) anim_tile2c();   /* */
	else if (t == 0x2B) anim_tile2b();
	else if (t == 0x1B) anim_tile1b();   /* 2A31:0DB7 -> 37F0:0676 (lever5.c) */   /* 2A31:0E07 -> 37F0:040A (shadow13.c) */   /* 2A31:0DCB -> 37F0:0588 (bridge5.c) */
	else if (level_kind == 6 && t == 0x1F) anim_tile1f();   /* 33FD:15A2 (OVL08, final.c) */
	else if (level_kind == 6 && t == 0x28) anim_tile28();   /* 33FD:162A */
	else if (level_kind == 6 && t == 0x29) anim_tile29();   /* 33FD:17AC */
	else if (level_kind == 6 && t == 0x2A) anim_tile2a();   /* 33FD:19B4 */
	else if (t < 4 || t > 0x2C || t == 7 || t == 8 || t == 9 || t == 0xC || t == 0xE || t == 0xF || t == 0x10 || t == 0x12 || t == 0x14 || t == 0x15 || t == 0x16
	         || t == 0x18 || t == 0x19 || t == 0x1A || t == 0x21 || t == 0x23) cur_trob.state = 0xFF;
	else anim_tile_other(t);
	((uint16_t *)&anim_attrs[(int8_t)cur_trob.tilepos])[0] = (uint16_t)anim_mod;
}
/* 1375:0006 */
void animate_tiles(void)
{
	if (trob_count == 0) return;
	int removed = 0;
	for (int i = 0; i < (int16_t)trob_count; i++) {
		cur_trob = trobs[i]; anim_index = i; animate_tile(); trobs[i].state = cur_trob.state;
		if ((int8_t)cur_trob.state < 0) removed = 1;
	}
	if (removed) { int n = 0; for (int i = 0; i < (int16_t)trob_count; i++) if ((int8_t)trobs[i].state >= 0) trobs[n++] = trobs[i]; trob_count = n; }
}
/* 1375:1414: start (or restart) the animation of a tile */
void add_trob(uint8_t tile, uint8_t state, int8_t tilepos, uint8_t room)
{
	for (int i = 0; i < (int16_t)trob_count; i++) if (trobs[i].tilepos == tilepos && trobs[i].room == room) { trobs[i].state = state; return; }   /* 1375:2598 */
	if (trob_count < 20) { cur_trob = (trob_type){tilepos, room, state, tile}; trobs[trob_count++] = cur_trob; }   /* the new entry is built in cur_trob */
}
/* 0823:0B78: start the animations of the tiles on screen: the drawn room, the left room's right column and
 * the lower room's top row (the left column comes from the draw buffer DS:5C5E in the original; same tiles) */
void start_room_anims(void)
{
	uint8_t room = drawn_room; int8_t tp = 0;
	for (int si = 0; si < 0x2B; si++, tp++) {
		uint8_t t;
		if (si == 0x1E) { if (room_L) { room = room_L; room_pointers(room); } else si += 3; }
		if (si == 0x21) { if (!room_B) break; room = room_B; room_pointers(room); }
		if (si < 0x1E) { room_pointers(room); tp = si; anim_mod = anim_attrs[si]; t = anim_tiles[si]; }
		else if (si < 0x21) { tp = (si - 0x1E) * 10 + 9; t = anim_tiles[tp]; }
		else { tp = si - 0x21; anim_mod = anim_attrs[tp]; t = anim_tiles[tp]; }
		switch (t) {
		case 0x1C: case 0x1D: case 0x1F: case 0x25: case 0x26: case 0x27: case 0x28: case 0x2B: add_trob(t, 1, tp, room); break;
		case 0x0A: if (si < 0x21) start_0a(tp, room); break;
		case 0x13: case 0x20: start_torch(tp, room); break;
		case 0x02: trap_room_entry(tp, room); break;   /* 186A:0226 (every kind: the tile only exists on kind 3) */
		case 0x17: if (level_kind == 3) { if (si < 0x21) floor_room_entry(room, tp); break; } anim_start_other(t, tp, room, si); break;   /* 33FD:0A54 */
		case 0x1E: if (level_kind == 1) { tile1e_start(room, tp, 3); break; } anim_start_other(t, tp, room, si); break;   /* 33FD:0A18 */
		case 0x2C: anim_start_2c(anim_attrs, tp, room); break;   /* 2A31:0DF3 -> 37F0:0742 */
		default: if ((room == 6 || room == 7 || room == 8) && level_kind == 6 && (anim_mod & 0x1000)) anim_start_final(anim_attrs, tp, room); break;   /* 33FD:1962 / 1B94 */
		}
	}
	room_pointers(drawn_room);
}
int anim_visible_pub(void) { return anim_visible(); }
void start_0a_pub(int8_t tp, uint8_t room) { start_0a(tp, room); }

// ==== beast.c
int blocks(uint8_t t) { return tile_is_wall_kind(t) && !(t == 7 && (curr_modifier & 0x80)); }
   /* 7 with bit 7: an open door */
int standable(uint8_t t) { return tile_is_floor(t) || (t == 7 && (curr_modifier & 0x80)); }
/* 366C:1632: facing the prince? */
int beast_facing(void)
{
	if (Char.f19 == 0xAB || Char.f23 < 2) return 0;
	return (Char.direction == 0 && Char.curr_col <= Opp.curr_col) || (Char.direction == -1 && Char.curr_col >= Opp.curr_col);
}
int opp_frame_open(void) { uint16_t f = Opp.frame; return (f >= 1 && f <= 0xE) || (f >= 0x31 && f <= 0x38); }
   /* running / running jump */
/* 366C:122A: in reach: pounce when the prince comes running, else run at him */
void beast_attack(void)
{
	int pounce = 0, d = opp_distance();
	if (d >= 0xD && d <= 0x2D) {
		if (Char.frame == 0x116 || Char.frame == 0x117) pounce = 1;
		else if (Char.f19 == 0xB0 && opp_frame_open()) pounce = 1;
		else if (Char.f19 != 0xB0 && Char.f19 != 0xAD) { seqtbl_offset_char(0xB0); play_sound(0x47); }
	} else {
		if (Char.f19 == 0xB0 && opp_frame_open() && d > 0xD && d < 0x32) pounce = 1;
		else if (Char.f19 == 0xB0 && Opp.frame >= 0x87 && Opp.frame <= 0x95 && d > 0xD && d < 0x2D) pounce = 1;
		else if ((Char.frame == 0x116 || Char.frame == 0x117) && (d < 0xD || d > 0x31) && standable(get_tile_infrontof(1))) seqtbl_offset_char(0xB1);
	}
	if (pounce && Char.f19 != 0xAD) { Char.x = char_dx_forward(d - 0x20); seqtbl_offset_char(0xAD); }
}
/* 366C:1368: waiting; when the timer runs out, face the prince if he is in reach on this row, else turn around */
void beast_wait(level_char_init *r)
{
	uint8_t *timer = (uint8_t *)&r->y;
	if ((int8_t)--*timer > 0) return;
	*timer = 0xFF;
	int8_t left = scan_to_wall_pub(-1, Char.curr_row, Char.curr_col, Char.room), right = scan_to_wall_pub(1, Char.curr_row, Char.curr_col, Char.room);
	uint8_t t = get_tile_at_char();
	if (Opp.room == Char.room && Opp.curr_row == Char.curr_row && Char.curr_col > left && Char.curr_col < right)
		Char.direction = (Char.curr_col > Opp.curr_col || blocks(t)) ? -1 : 0;
	else Char.direction = ~Char.direction;
	if (blocks(t)) { seqtbl_offset_char(0xAA); Char.x = char_dx_forward(0x26); }
	else seqtbl_offset_char(0xAC);
	Char.f24 = 0;
}
/* 366C:1474: hunting (timer < 0, not facing the prince) */
void beast_hunt(level_char_init *r)
{
	if (Opp.alive >= 0) { if (Char.f19 != 0xB0 && Char.frame != 0x116 && Char.frame != 0x117) seqtbl_offset_char(0xB0); return; }
	if (Char.f19 != 0xAB && Char.f19 != 0xAC && Char.f24 != 9) {
		get_tile_at_char();
		if (((curr_modifier >> 8) & 0xF) == 0xC) {   /* a ledge mark: line up with it */
			int si = (Char.x - 0x90) % 32;
			if (si < 0xE || si > 0x12) return;
			si = 0x10 - si; if (Char.direction == -1) si = -si; else si += 8;
			Char.x = char_dx_forward(si); seqtbl_offset_char(0xAB); return;
		}
		uint8_t t = get_tile_infrontof(1);
		if (Char.f19 == 0xB0 || Char.f19 == 0xA8 || Char.frame == 0x116 || Char.frame == 0x117) { if (standable(t)) seqtbl_offset_char(0xB1); return; }
		if (standable(t)) return;
		if (!tile_is_wall_kind(t)) { seqtbl_offset_char(0xB0); return; }
		if (t == 7 || (Char.direction != 0 && Char.frame == 0xFE)) { seqtbl_offset_char(0xA8); return; }
		if (Char.direction == 0) Char.f24 = 9;
		return;
	}
	if (Char.f24 == 9) {
		uint8_t t = get_tile_at_char(); int16_t d = distance_to_edge_weight();
		if (tile_is_wall_kind(t) && d < 8) { Char.frame = 0x108; seqtbl_offset_char(0xA8); }
	}
	if (Char.frame == 0x108) { Char.f24 = 6; *(uint8_t *)&r->y = Char.f23 == 2 ? 6 : random_2751(0x3C) + 0x24; }
}
