int x_centred(int16_t x, int tol) { int r = (x - 0x90) % 32; return 0x10 - tol <= r && r <= tol + 0x10; }
int y_centred(int16_t y, int tol) { int r = (y - 3) % 63; return 0x1F - tol <= r && r <= tol + 0x1F; }
