// ==== sound.c
   /* the pass's end (1611:04D0 after the tick and the drawing): this long after its start */

uint32_t vlq(const uint8_t *b, int *i, int n) { uint32_t v = 0; while (*i < n) { uint8_t c = b[(*i)++]; v = v << 7 | (c & 0x7F); if (!(c & 0x80)) break; } return v; }
/* a MIDISND piece: byte 2 then a format-0 standard MIDI file, played by a 240 Hz interrupt that adds a 16.16 tick
 * increment (194C:2FB4: trunc(trunc(256e6 / 240) * 65536 / trunc(tempo * 256 / 480)), each division truncating) until
 * the end-of-track event's tick. The driver reads a tempo's three bytes as the high byte then a little-endian word
 * (194C:3171), so 0x0C3500 (75 bpm) plays as 0x0C0035. Returns microseconds. */
uint32_t midi_inc(uint32_t tempo) { uint32_t q = (uint32_t)((uint64_t)tempo * 256 / 480); return q ? (uint32_t)((uint64_t)(256000000u / 240) * 65536 / q) : 0; }
uint32_t midi_length(const uint8_t *b, int n)
{
	if (n < 23 || memcmp(b + 1, "MThd", 4) || memcmp(b + 15, "MTrk", 4)) return 0;
	int j = 23, end = n; uint8_t run = 0; uint64_t pos = 0, at = 0, irq = 0; uint32_t inc = midi_inc(500000);
	while (j < end) {
		at += (uint64_t)vlq(b, &j, end) << 16;   /* the event's tick (16.16); the counter reaches it on an interrupt */
		if (at > pos && inc) { uint64_t k = (at - pos + inc - 1) / inc; irq += k; pos += k * inc; }
		if (j >= end) break;
		uint8_t c = b[j];
		if (c == 0xFF) { if (j + 1 >= end || b[j + 1] == 0x2F) break; uint8_t ty = b[j + 1]; j += 2; uint32_t l = vlq(b, &j, end);
			if (ty == 0x51 && l == 3 && j + 3 <= end) inc = midi_inc((uint32_t)(b[j] << 16 | b[j + 2] << 8 | b[j + 1]));
			j += l; }
		else if (c == 0xF0 || c == 0xF7) { j++; j += vlq(b, &j, end); }
		else { if (c & 0x80) { run = c; j++; } j += ((run & 0xF0) == 0xC0 || (run & 0xF0) == 0xD0) ? 1 : 2; }
	}
	return (uint32_t)(irq * 1000000 / 240);
}
void snd_load(void)
{
	if (snd_loaded) return;
	snd_loaded = 1;
	 const char *dir = glue_dir[0] ? glue_dir : getenv("PRINCE2_DIR"); if (!dir) return;
	char p[512]; dat_file d; uint16_t n;
	snprintf(p, sizeof p, "%s/DIGISND.DAT", dir);
	if (dat_open(&d, p)) for (int i = 0; i < NSND; i++) { const uint8_t *r = dat_find(&d, "DNS", 10000 + i, &n); if (r && n >= 6) { unsigned rate = r[1] | r[2] << 8, len = r[4] | r[5] << 8; snd_kind[i] = 1;
		if (r[3] == 0xFF && n >= 12) len = r[10] | r[11] << 8;   /* packed (0x20 0x26 0x2F 0x31 0x36 0x258): the unpacked length at +0xA (docs/AUDIO.md) */
		snd_len[i] = (r[0] & 0x80) ? 0x7FFFFFFF : (uint32_t)((double)len * 1e6 / (rate ? rate : 11000)); } }   /* byte 0 bit 7: loops until stopped */
	snprintf(p, sizeof p, "%s/MIDISND.DAT", dir);
	if (dat_open(&d, p)) for (int i = 0; i < NSND; i++) { const uint8_t *r = dat_find(&d, "DNS", 10000 + i, &n); if (r && !snd_kind[i] && (r[0] & 2)) { snd_kind[i] = 2; snd_len[i] = (r[0] & 0x80) ? 0x7FFFFFFF : midi_length(r, n); } }   /* byte 0: 2 MIDI, 0x80 loops (level 14's room music) */
}
